# Validate that a concept is active and within the field's value set (ECL-based)
GET /fhir/ValueSet/$validate-code
  ?url=http://snomed.info/sct?fhir_vs=ecl/<<404684003
  &system=http://snomed.info/sct
  &code=73211009
  &displayLanguage=en

# Response - concept is valid and within the value set
{
  "resourceType": "Parameters",
  "parameter": [
    { "name": "result", "valueBoolean": true },
    { "name": "display", "valueString": "Diabetes mellitus" }
  ]
}

# Response - concept not in value set (e.g. a procedure submitted to a findings field)
{
  "resourceType": "Parameters",
  "parameter": [
    { "name": "result", "valueBoolean": false },
    { "name": "message", "valueString": "The code 71388002 is not in the value set" }
  ]
}

{
  "resourceType": "ValueSet",
  "id": "diabetes-mellitus-cds",
  "url": "https://example.org/ValueSet/diabetes-mellitus-cds",
  "version": "20250301",
  "name": "DiabetesMellitusCDS",
  "title": "Diabetes mellitus - CDS rule value set",
  "status": "active",
  "description": "All types of diabetes mellitus for use in CDS rules. Intensional definition using ECL subsumption.",
  "compose": {
    "include": [
      {
        "system": "http://snomed.info/sct",
        "filter": [
          {
            "property": "constraint",
            "op": "=",
            "value": "<<73211009 |Diabetes mellitus (disorder)|"
          }
        ]
      }
    ]
  }
}

# Check whether a patient's concept is within the CDS rule's value set
GET /fhir/ValueSet/$validate-code
  ?url=https://example.org/ValueSet/diabetes-mellitus-cds
  &system=http://snomed.info/sct
  &code=44054006

# Response: result=true means the patient concept is within the rule's value set
{
  "resourceType": "Parameters",
  "parameter": [
    { "name": "result", "valueBoolean": true },
    { "name": "display", "valueString": "Type 2 diabetes mellitus" }
  ]
}

{
  "resourceType": "ValueSet",
  "id": "diabetes-mellitus-cohort",
  "url": "https://example.org/ValueSet/diabetes-mellitus-cohort",
  "version": "20250301",
  "name": "DiabetesMellitusCohort",
  "title": "Diabetes Mellitus Cohort",
  "status": "active",
  "description": "All subtypes of diabetes mellitus for cohort identification and analytics",
  "compose": {
    "include": [
      {
        "system": "http://snomed.info/sct",
        "filter": [
          {
            "property": "constraint",
            "op": "=",
            "value": "<<73211009 |Diabetes mellitus (disorder)|"
          }
        ]
      }
    ]
  }
}

# Translate a SNOMED CT concept to ICD-10 using the official map
POST /fhir/ConceptMap/$translate
Content-Type: application/fhir+json

{
  "resourceType": "Parameters",
  "parameter": [
    {
      "name": "url",
      "valueUri": "http://snomed.info/sct/900000000000207008?fhir_cm=447562003"
    },
    {
      "name": "system",
      "valueUri": "http://snomed.info/sct"
    },
    {
      "name": "code",
      "valueCode": "44054006"
    },
    {
      "name": "targetsystem",
      "valueUri": "http://hl7.org/fhir/sid/icd-10"
    }
  ]
}

# Response
{
  "resourceType": "Parameters",
  "parameter": [
    { "name": "result", "valueBoolean": true },
    {
      "name": "match",
      "part": [
        { "name": "equivalence", "valueCode": "equivalent" },
        {
          "name": "concept",
          "valueCoding": {
            "system": "http://hl7.org/fhir/sid/icd-10",
            "code": "E11",
            "display": "Type 2 diabetes mellitus"
          }
        }
      ]
    }
  ]
}

{
  "resourceType": "Condition",
  "id": "condition-diabetes",
  "clinicalStatus": {
    "coding": [{
      "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
