# Failure: concept not found in declared version/edition
{
  "resourceType": "Parameters",
  "parameter": [
    { "name": "result", "valueBoolean": false },
    { "name": "message", "valueString": "Unknown code '99999999' in system 'http://snomed.info/sct'" }
  ]
}

# Failure: concept inactive (inactivated in this version)
{
  "resourceType": "Parameters",
  "parameter": [
    { "name": "result", "valueBoolean": false },
    { "name": "message", "valueString": "Code '154283005' is not active in version 'http://snomed.info/sct/900000000000207008/version/20250301'" }
  ]
}

# Failure: concept valid but outside the declared value set scope
{
  "resourceType": "Parameters",
  "parameter": [
    { "name": "result", "valueBoolean": false },
    { "name": "message", "valueString": "Code is valid but not in the specified value set" }
  ]
}

# Retrieve preferred term using a specific language reference set
GET /fhir/CodeSystem/$lookup
  ?system=http://snomed.info/sct
  &code=44054006
  &displayLanguage=en-NZ

# To use a specific language reference set (Snowstorm extension)
GET /fhir/CodeSystem/$lookup
  ?system=http://snomed.info/sct
  &code=44054006
  &property=designation
  &_format=json

# Response
{
  "resourceType": "Parameters",
  "parameter": [
    { "name": "name", "valueString": "Diabetes mellitus type 2" },
    { "name": "display", "valueString": "Diabetes mellitus type 2" },
    {
      "name": "designation",
      "part": [
        { "name": "language", "valueCode": "en" },
        { "name": "use", "valueCoding": {
            "system": "http://snomed.info/sct",
            "code": "900000000000548007",
            "display": "PREFERRED"
          }
        },
        { "name": "value", "valueString": "Diabetes mellitus type 2" }
      ]
    }
  ]
}

