  ?system=http://snomed.info/sct
  &code=44054006
  &source=http://snomed.info/sct
  &target=http://hl7.org/fhir/sid/icd-10
  &url=http://snomed.info/sct/900000000000207008?fhir_cm=447562003

# Response - ConceptMap $translate result
{
  "resourceType": "Parameters",
  "parameter": [
    {
      "name": "result",
      "valueBoolean": true
    },
    {
      "name": "match",
      "part": [
        {
          "name": "equivalence",
          "valueCode": "narrower"
        },
        {
          "name": "concept",
          "valueCoding": {
            "system": "http://hl7.org/fhir/sid/icd-10",
            "code": "E11",
            "display": "Type 2 diabetes mellitus"
          }
