}

# Retrieve preferred term in a specific language using FHIR $lookup
GET /fhir/CodeSystem/$lookup
  ?system=http://snomed.info/sct
  &code=73211009
  &displayLanguage=nl

# Response
{
  "resourceType": "Parameters",
  "parameter": [
    { "name": "name",    "valueString": "SNOMED CT" },
    { "name": "display", "valueString": "Diabetes mellitus" },
    {
      "name": "designation",
      "part": [
        { "name": "language", "valueCode": "nl" },
        { "name": "use",      "valueCoding": { "code": "900000000000548007", "display": "Preferred" } },
        { "name": "value",    "valueString": "diabetes mellitus" }
      ]
    }
  ]
}

# Note: if no preferred term exists for nl, Snowstorm falls back
# to the next configured language reference set.
